361	/// Runtime state for enforcing a [`HappensBeforeProgram`] inside the scheduler.
362	///
363	/// The scheduler holds each edge's AFTER anchor -- removing that thread from the
364	/// run queue -- until the edge's BEFORE anchor has *fired*, so an authored
365	/// partial order deterministically reproduces a known race instead of relying on
366	/// a seed lottery. An anchor "fires" when its thread is granted passage past the
367	/// corresponding checkpoint (see [`Scheduler::hb_checkpoint`]).
368	///
369	/// Only [`Position::SyscallCount`] anchors are enforced in this milestone. Other
370	/// position kinds are retained for diagnostics but never fire; [`HbRuntime::new`]
371	/// warns about them so a run never silently ignores an ordering constraint.
372	#[derive(Debug)]
373	struct HbRuntime {
374	    /// The validated, normalized program (anchors indexed by name, plus edges).
375	    program: HappensBeforeProgram,
376	    /// Names of anchors that have fired. Monotonic: an anchor fires at most once,
377	    /// when its thread is first granted passage past it.
378	    fired: BTreeSet<String>,
379	    /// Threads currently parked at an AFTER anchor, out of the run queue, awaiting
380	    /// their gating BEFORE anchor(s). A `BTreeSet` keeps re-admission order
381	    /// deterministic.
382	    parked: BTreeSet<DetTid>,
383	    /// Threads observed at creation time, in deterministic spawn order, so an
384	    /// anchor addressed by `spawn_ordinal` resolves to a concrete `DetTid`.
385	    /// Index 0 is the root thread; index N (1-based) is the Nth spawned child,
386	    /// matching [`ThreadRef::spawn_ordinal`] semantics.
387	    spawn_order: Vec<DetTid>,
388	    /// Set when a newly fired anchor may have opened a parked thread's gate, so
389	    /// [`Scheduler::hb_flush_wakes`] re-admits parked threads at the next
390	    /// `step3` boundary. Re-admission is *deferred* to that boundary because it
391	    /// pushes to the run queue, which is illegal while a `tentative_pop`
392	    /// selection is in progress (as it is inside `block_for_one_resource`,
393	    /// where anchors fire).
394	    wake_pending: bool,
395	}
396	
397	impl HbRuntime {
398	    /// Build runtime state from a normalized program, warning about any anchor
399	    /// whose position kind this milestone does not enforce.
400	    fn new(program: HappensBeforeProgram) -> Self {
401	        for anchor in program.unenforced_positions() {
402	            tracing::warn!(
403	                "[happens-before] anchor {} uses position '{}', which the scheduler does not yet \
404	                 enforce (only 'after N syscalls' is enforced); this ordering constraint will NOT \
405	                 be applied",
406	                anchor.name,
407	                anchor.position,
408	            );
409	        }
410	        Self {
411	            program,
412	            fired: BTreeSet::new(),
413	            parked: BTreeSet::new(),
414	            spawn_order: Vec::new(),
415	            wake_pending: false,
416	        }
417	    }
418	
419	    /// Record a thread at creation time for `spawn_ordinal` resolution. Idempotent
420	    /// and cheap; the root thread lands at index 0, the Nth child at index N.
421	    fn note_spawn(&mut self, dettid: DetTid) {
422	        if !self.spawn_order.contains(&dettid) {
423	            self.spawn_order.push(dettid);
424	        }
425	    }
426	
427	    /// True when `tref` resolves to `dettid`, by explicit `DetTid` or by
428	    /// `spawn_ordinal` against the observed spawn order.
429	    fn thread_matches(&self, tref: &ThreadRef, dettid: DetTid) -> bool {
430	        if let Some(d) = tref.dettid {
431	            return d == dettid;
432	        }
433	        if let Some(ord) = tref.spawn_ordinal {
434	            return self.spawn_order.get(ord as usize).copied() == Some(dettid);
435	        }
436	        false
437	    }
438	
439	    /// Names of anchors on `dettid` whose enforced position is exactly
440	    /// `SyscallCount(count)`.
441	    fn anchors_at_syscall(&self, dettid: DetTid, count: u64) -> Vec<String> {
442	        self.program
443	            .anchors
444	            .values()
445	            .filter(|a| {
446	                matches!(a.position, Position::SyscallCount(n) if n == count)
447	                    && self.thread_matches(&a.thread, dettid)
448	            })
449	            .map(|a| a.name.clone())
450	            .collect()
451	    }
452	
453	    /// True when anchor `name` is the AFTER endpoint of a Hard edge whose BEFORE
454	    /// endpoint has not yet fired -- i.e. a thread reaching `name` must be held.
455	    fn anchor_blocked(&self, name: &str) -> bool {
456	        self.program.edges.iter().any(|e| {
457	            e.after == name && e.strength == Strength::Hard && !self.fired.contains(&e.before)
458	        })
459	    }
460	}
461	
462	/// Which end of a thread's priority band a run-queue admission targets.
463	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
464	pub(crate) enum AdmitSide {
465	    /// Run before an equal-priority peer (`runqueue_push_front`).
466	    Front,
467	    /// Ordinary tail admission (`runqueue_push_back`).
468	    Back,
469	}
470	
471	/// How a run-queue admission's side is determined.
472	///
473	/// The side is *resolved* — not merely applied — at the deterministic drain
474	/// ([`Scheduler::drain_pending_run_queue_admissions`]). Buffering the *intent*
475	/// rather than an already-chosen `AdmitSide` is what keeps the admission a pure
476	/// function of deterministic scheduler state: any PRNG draw that picks the side
477	/// (`RunsPostFork::Random`) is consumed at the drain, in canonical `DetTid`
478	/// order, instead of in host RPC / lock-acquisition order at the handler. See
479	/// [`Scheduler::admit_to_run_queue`].
480	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
481	pub(crate) enum AdmitIntent {
482	    /// The side is fixed regardless of scheduler state; consumes no PRNG.
483	    Fixed(AdmitSide),
484	    /// The side follows the post-fork policy; `RunsPostFork::Random` draws from
485	    /// the scheduler PRNG at resolution time.
486	    PostFork(RunsPostFork),
487	}
488	
489	/// Why a raw TID must be removed from the physical run queue at the next
490	/// deterministic drain.
491	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
492	enum RemovalDisposition {
493	    /// The current thread incarnation is gone. Any admission recorded for the
494	    /// same raw TID is stale and must be cancelled.
495	    Retire,
496	    /// Linux nonleader exec destroyed the old process leader and reassigned
497	    /// its raw TID to the caller's replacement image. Remove the old physical
498	    /// queue slot, but preserve the one causally paired replacement admission.
499	    ReplaceThenAdmit,
500	}
501	
502	#[derive(Debug, Clone, PartialEq, Eq)]
503	enum WaitidSignalRequest {
504	    /// An in-flight wait that a pending signal should wake: either the legacy
505	    /// `waitid` kernel-polling loop or a scheduler-managed child-wait lifecycle
506	    /// resource.
507	    ///
508	    /// Deliberately does NOT distinguish the two. Queue residency is not a
509	    /// property of the resource and must be decided at the drain, not inferred
510	    /// here: `wake_child_waiters` re-admits a waiter without clearing its
511	    /// `WaitChild` request, and `step6_reenqueue` pushes a thread back before it
512	    /// issues its next request, so either request can be held by a thread that
513	    /// is already in the run queue.
514	    Parked,
515	    Pending(Vec<SigWrapper>),
516	}
