1261	/// Wait without manufacturing a normal scheduler request or response. The
1262	/// caller must check the terminal state again under the mutex before mutation.
1263	async fn until_backend_failure<T>(
1264	    sched: &Arc<Mutex<Scheduler>>,
1265	    wait: impl std::future::Future<Output = T>,
1266	) -> Result<T, SkipTurn> {
1267	    let failure = {
1268	        let sched = sched.lock().unwrap();
1269	        if sched.backend_failed() {
1270	            return Err(SkipTurn);
1271	        }
1272	        sched.backend_failure_waiter()
1273	    };
1274	    futures::pin_mut!(wait, failure);
1275	    match futures::future::select(failure, wait).await {
1276	        futures::future::Either::Left((notice, _)) => {
1277	            notice.expect("scheduler owns the failure sender until publication");
1278	            Err(SkipTurn)
1279	        }
1280	        futures::future::Either::Right((value, _)) => Ok(value),
1281	    }
1282	}
1283	
1284	/// Advance turn by 1 turn, blocking when necessary to make it happen.
1285	/// Return the outcome of the turn as well as which resources were used, if any.
1286	///
1287	/// WARNING: this is duplicated with the non-blocking `step` function below.
1288	/// TODO: this duplication is temporary and they should be either combined or one removed soon.
1289	async fn do_ordinary_turn_blocking(
1290	    sched: Arc<Mutex<Scheduler>>,
1291	    global_time: Arc<Mutex<GlobalTime>>,
1292	    last_turn: &Result<Resources, SkipTurn>,
1293	) -> Result<Resources, SkipTurn> {
1294	    // Loop until all threads are parked, then proceed:
1295	    //
1296	    // TODO: First, this check can move after step2, before we commit the action. Second,
1297	    // it can later grow more sophisticated to only check the completion of dependent
1298	    // actions, not all outsanding guest actions.
1299	    loop {
1300	        // We must read the queue carefully, because it can grow in the background
1301	        // everytime we await.  However, while it can *grow*, it cannot change order, as
1302	        // only the scheduler thread (us) actually rotates entries from the front to the back.
1303	        let req_ivar = {
1304	            let mut mg = sched.lock().unwrap();
1305	            if mg.backend_failed() {
1306	                return Err(SkipTurn);
1307	            }
1308	            let arc = global_time.clone();
1309	
1310	            let next_outstanding = mg.step1_check_quiescence(&arc, last_turn);
1311	            match next_outstanding {
1312	                None => {
1313	                    trace!("Scheduler observed full quiescense, proceeding...");
1314	                    break;
1315	                }
1316	                Some(iv) => iv.clone(),
1317	            }
1318	        };
1319	        trace!("Scheduler wait for full quiescense, on {}...", req_ivar);
1320	        let _ = until_backend_failure(&sched, req_ivar).await?;
1321	    }
1322	
1323	    // Here we copy some information while holding the sched lock, and then release it so
1324	    // we can `.await` below:
1325	    let (next_dtid, req, resp) = {
1326	        let mut sched = sched.lock().unwrap();
1327	        if sched.backend_failed() {
1328	            return Err(SkipTurn);
1329	        }
1330	        sched.step2_process_blocked(&global_time)?;
1331	        sched.step3_peek().ok_or(SkipTurn)?
1332	    };
1333	
1334	    finish_selected_turn(sched, global_time, next_dtid, req, resp).await
1335	}
1336	
1337	pub async fn do_a_turn_blocking(
1338	    sched: Arc<Mutex<Scheduler>>,
1339	    global_time: Arc<Mutex<GlobalTime>>,
1340	    last_turn: &Result<Resources, SkipTurn>,
1341	) -> Result<Resources, SkipTurn> {
1342	    let controlled = sched.lock().unwrap().kvm_shared_dequeue_timers;
1343	    if !controlled {
1344	        return do_ordinary_turn_blocking(sched, global_time, last_turn).await;
1345	    }
1346	    let result = async {
1347	        // A control pause retains both its maintenance position and the unpaid
1348	        // obligation of the preceding real turn. Transport messages never pay it.
1349	        enum Action {
1350	            Wait {
1351	                request: Option<Ivar<SchedRequest>>,
1352	                control: Ivar<()>,
1353	                barrier: bool,
1354	            },
1355	            Select(DetTid, Ivar<SchedRequest>, Ivar<SchedResponse>),
1356	        }
1357	        let mut charged = false;
1358	        let mut refresh = false;
1359	        let mut maintenance = 0;
1360	        // The reference admits one due event before a selection. Control
1361	        // callbacks may refresh observed time, but must not spend that event
1362	        // budget again and reverse ordinary sleepers' queue-front order.
1363	        let mut timed_event_processed = false;
1364	        let mut empty_queue_skip = false;
1365	        loop {
1366	            signal_control::flush_signal_failures(&sched);
1367	            let action = {
1368	                let mut state = sched.lock().unwrap();
1369	                state.drain_control_intents();
1370	                if state.backend_failed() {
1371	                    return Err(SkipTurn);
1372	                }
1373	                let barrier = state.control_barrier();
1374	                if empty_queue_skip && !barrier {
1375	                    return Err(SkipTurn);
1376	                }
1377	                let request = state.are_all_quiesced();
1378	                if !barrier && request.is_none() {
1379	                    if !charged {
1380	                        state.bump_global_time(&global_time, last_turn);
1381	                        charged = true;
1382	                    } else if refresh {
1383	                        // A hook can advance real observed logical time. Refresh
1384	                        // eligibility without charging again. An earlier empty
1385	                        // due check leaves the one-event budget available; an
1386	                        // actual pop consumes it until this turn returns.
1387	                        state.bump_global_time(&global_time, &Err(SkipTurn));
1388	                        if !timed_event_processed {
1389	                            timed_event_processed = state.step2b_process_timed();
1390	                        }
1391	                        if let Err(error) = state.select_parked_alarm() {
1392	                            state.fail_parked_selection(error);
1393	                            continue;
1394	                        }
1395	                    }
1396	                    refresh = false;
1397	                    if state.are_all_quiesced().is_some() {
1398	                        continue;
1399	                    }
1400	                    match maintenance {
1401	                        0 => {
1402	                            state.step2_drain_prefix()?;
1403	                            maintenance = 1;
1404	                            continue;
1405	                        }
1406	                        1 => {
1407	                            if !timed_event_processed {
1408	                                timed_event_processed = state.step2b_process_timed();
1409	                            }
1410	                            if let Err(error) = state.select_parked_alarm() {
1411	                                state.fail_parked_selection(error);
1412	                            }
1413	                            maintenance = 2;
1414	                            continue;
1415	                        }
1416	                        2 => {
1417	                            state.step2c_process_io_blockers()?;
1418	                            maintenance = 3;
1419	                            continue;
1420	                        }
1421	                        3 => {
1422	                            state.step2e_process_signal_deferred();
1423	                            maintenance = 4;
1424	                            continue;
1425	                        }
1426	                        4 => {
1427	                            empty_queue_skip =
1428	                                state.step2d_handle_empty_queue(&global_time).is_err();
1429	                            // Select at the time to which the empty queue just
1430	                            // advanced, before a later pass can advance again.
1431	                            if let Err(error) = state.select_parked_alarm() {
1432	                                state.fail_parked_selection(error);
1433	                            }
1434	                            maintenance = 5;
1435	                            continue;
1436	                        }
1437	                        _ => {
1438	                            if let Err(error) = state.select_parked_alarm() {
1439	                                state.fail_parked_selection(error);
1440	                                continue;
1441	                            }
1442	                            // Installing an observation creates an empty callback
1443	                            // gate. Await its hook/finish before any tentative pop.
1444	                            if state.are_all_quiesced().is_some() {
1445	                                continue;
1446	                            }
1447	                            let (tid, req, resp) = state.step3_peek().ok_or(SkipTurn)?;
1448	                            Action::Select(tid, req, resp)
1449	                        }
1450	                    }
1451	                } else {
1452	                    Action::Wait {
1453	                        request,
1454	                        control: state.control_waiter(),
1455	                        barrier,
1456	                    }
1457	                }
1458	            };
1459	            match action {
1460	                Action::Select(tid, req, resp) => {
1461	                    return finish_selected_turn(
1462	                        sched.clone(),
1463	                        global_time.clone(),
1464	                        tid,
1465	                        req,
1466	                        resp,
1467	                    )
1468	                    .await;
1469	                }
1470	                Action::Wait {
1471	                    request,
1472	                    control,
1473	                    barrier,
1474	                } => {
1475	                    if barrier {
1476	                        until_backend_failure(&sched, control).await?;
1477	                    } else if let Some(request) = request {
1478	                        let wait = async {
1479	                            futures::pin_mut!(request, control);
1480	                            let _ = futures::future::select(request, control).await;
1481	                        };
1482	                        until_backend_failure(&sched, wait).await?;
1483	                    }
1484	                    refresh = true;
1485	                }
1486	            }
1487	        }
1488	    }
1489	    .await;
1490	    signal_control::flush_signal_failures(&sched);
1491	    result
1492	}
1493	
1494	/// Complete the selected transaction. Keeping the await and post-await checks
1495	/// together also lets native controls hold the real request wait open while
1496	/// consuming cleanup races with the daemon.
1497	pub(crate) async fn finish_selected_turn(
1498	    sched: Arc<Mutex<Scheduler>>,
1499	    global_time: Arc<Mutex<GlobalTime>>,
1500	    next_dtid: DetTid,
1501	    req: Ivar<SchedRequest>,
1502	    resp: Ivar<SchedResponse>,
1503	) -> Result<Resources, SkipTurn> {
1504	    // Step 1B: wait for the selected thread to make its request.
1505	    trace!(
1506	        "[sched-daemon] waiting for next thread (dtid {}) to park...",
1507	        next_dtid
1508	    );
1509	    let rsrcs: Resources = match until_backend_failure(&sched, req.get()).await? {
1510	        Err(ThreadExited) => {
1511	            debug!(
1512	                "[sched-daemon] woke up on request {}, but fizzling because next thread, {}, exited.",
1513	                &req, &next_dtid
1514	            );
1515	            // The selected thread died while we awaited its request, so this turn
1516	            // is skipped without reaching step4-6. `step3_peek` opened a
1517	            // tentative_pop for `next_dtid`; close it here (undo, since the turn
1518	            // did not commit) before returning. Otherwise the tentative selection
1519	            // outlives the turn, and the next pass's step2 removal drain calls
1520	            // `remove_tid` while `tentative_selection` is still `Some`, tripping
1521	            // the run queue's transaction guard -- the "reconnect panic moved one
1522	            // pass" defect. The dead thread's buffered removal drains
1523	            // deterministically on the next pass, once this undo has closed the
1524	            // window.
1525	            let mut sched = sched.lock().unwrap();
1526	            if !sched.backend_failed() {
1527	                sched.run_queue.undo_tentative_pop();
1528	            }
1529	            return Err(SkipTurn);
1530	        }
1531	        Ok(r) => r,
1532	    };
1533	    trace!("[sched-daemon] daemon woke up on {}...", &req);
1534	
1535	    // Since the scheduler is asynchronous, we need to check our assumptions.  Polling is
1536	    // sufficient here because the thread cannot be racing with us to exit since we know
1537	    // it is *already* parked.
1538	    let mut mg = sched.lock().unwrap();
1539	    if mg.backend_failed() {
1540	        return Err(SkipTurn);
1541	    }
1542	    mg.abort_turn_if_thread_vanished(next_dtid)?;
1543	
1544	    // The logical COMMIT point for the turn is during step4:
1545	    mg.step4_resource_block(next_dtid, &rsrcs, &resp)?;
1546	    mg.step5_guest_unblock(next_dtid, &rsrcs, &resp)?;
1547	    let sched_yield = rsrcs.resources.contains_key(&ResourceID::SchedYield);
1548	    mg.step6_reenquue(next_dtid, sched_yield);
1549	    if let Some(call) = rsrcs.as_exit_syscall() {
1550	        mg.step7_simulate_exit_posthook(next_dtid, call, &global_time);
1551	    }
1552	    Ok(rsrcs)
1553	}
1554	
1555	// A futex request contains only one resource request, for FutexWait.
1556	fn assert_futex_request(nextturn: &ThreadNextTurn) {
1557	    match nextturn.req.try_read() {
1558	        Some(Ok(req)) => {
1559	            if !(req.resources.contains_key(&ResourceID::FutexWait) && req.resources.len() == 1) {
1560	                panic!(
1561	                    "assert_empty_request({}): internal invariant broken, expected empty resource request, found: {:?}",
1562	                    nextturn.dettid, req
1563	                )
1564	            }
1565	        }
1566	        _ => panic!(
1567	            "assert_empty_request({}): internal invariant broken, expected request for zero resources, instead found no request.",
1568	            nextturn.dettid
1569	        ),
1570	    }
1571	}
1572	
1573	// Test if the request was from a futex_wait call.
1574	fn is_futex_request(nextturn: &ThreadNextTurn) -> bool {
1575	    match nextturn.req.try_read() {
1576	        Some(Ok(req)) => Scheduler::is_x_turn(&req, &ResourceID::FutexWait),
1577	        _ => false,
1578	    }
1579	}
1580	
1581	/// Until panics are escalated properly, this encapsulates a way to exit the hermit container
1582	/// entirely.
1583	pub fn immediate_fatal_exit() {
1584	    std::process::exit(1);
1585	}
1586	
1587	/// The result of consuming a SchedEvent during --replay-preemptions-from.  This represents some
1588	/// decisions about what to do next, but are actions which we cannot implement inside
1589	/// `consume_schedevent`.
1590	pub struct ConsumeResult {
1591	    /// Should we keep runnning this thread, if false we background the current thread after this schedevent to let the next thread run.
1592	    pub keep_running: bool,
1593	    /// A remaining (delta) timeslice this thread is required to run according to the replay schedule
1594	    pub timeslice_remaining: Option<LogicalTime>,
1595	    /// Should we print the stacktrace in the guest, as per --stacktrace-event
1596	    pub print_stack: MaybePrintStack,
1597	    /// The number of this event in the global total order of events.
1598	    #[allow(dead_code)]
1599	    pub event_ix: u64,
1600	}

