2125	                // waiting for the thread to park.
2126	                //
2127	                // WARNING: this try_put should potentially turn back into a put(), if we can narrow
2128	                // down the exit scenarios and ensure that they happen when the guest is running and
2129	                // has NOT filled its request to the scheduler yet.
2130	                let request_was_pending = nextturn.req.try_put(Err(ThreadExited)).is_some();
2131	                if request_was_pending && self.cancel_killed_thread_rpcs && !self.backend_failed() {
2132	                    // AUTONOMOUS-BOT-IMPLEMENTED
2133	                    // TODO-HUMAN-REVIEW(PR-845): Review killed-thread RPC cancellation.
2134	                    nextturn.resp.try_put(SchedResponse::Signaled(None));
2135	                }
