3925	    /// Post-await re-check: the selected thread parked (its request resolved
3926	    /// `Ok`), but did its `next_turns` entry survive until the daemon got the
3927	    /// lock back? If not, the turn must be abandoned.
3928	    ///
3929	    /// Returns `Err(SkipTurn)` for the abandoned case, after closing the
3930	    /// tentative window `step3_peek` opened. Two things hang on that `Err`:
3931	    ///
3932	    /// * The tentative pop is undone rather than committed, so the selection
3933	    ///   does not outlive the turn and the next pass's step2 removal drain does
3934	    ///   not call `remove_tid` against a live `tentative_selection` (the same
3935	    ///   hygiene the `Err(ThreadExited)` arm needs).
3936	    /// * The caller reports a SKIP, not a completed turn. This branch bypasses
3937	    ///   steps 4-7, so nothing is blocked, unblocked or re-enqueued -- yet
3938	    ///   `bump_global_time` suppresses its advance only on `last_turn.is_err()`
3939	    ///   ("if the last turn was a skip, it shouldn't really have time-bumped").
3940	    ///   Reporting `Ok` here therefore added a DETLOG-visible virtual-time tick
3941	    ///   for work that never happened, and whether this branch is reached at all
3942	    ///   depends on whether teardown cleared `next_turns` inside the host-timed
3943	    ///   gap between the await resolving and the re-lock -- so the same logical
3944	    ///   execution could gain that tick in one run and not the next.
3945	    fn abort_turn_if_thread_vanished(&mut self, next_dtid: DetTid) -> Result<(), SkipTurn> {
3946	        if self.next_turns.contains_key(&next_dtid) {
3947	            return Ok(());
3948	        }
3949	        info!(
3950	            "[sched-daemon] thread {} exited, skipping over...",
3951	            &next_dtid
3952	        );
3953	        self.run_queue.undo_tentative_pop();
3954	        Err(SkipTurn)
3955	    }
