3964	    /// Step: Determine if action will block based on current information.  E.g. will it block
3965	    /// on a pipe read with no writer? If so, register it in the blocked_pool and issue a "skip".
3966	    /// We can go ahead and take resource locks and physically issue the blocking effect if we
3967	    /// like.  It's immaterial whether we do that now or later.
3968	    ///
3969	    /// Postcondition:
3970	    ///  - If returning SkipTurn, this function ENDS the Scheduler turn, advancing to the
3971	    ///    next (skipping subsequent steps within theturn).  Otherwise, it waits for a
3972	    ///    later step end the turn.
3973	    #[allow(clippy::unnecessary_wraps)]
3974	    fn step4_resource_block(
3975	        &mut self,
3976	        dettid: DetTid,
3977	        rs: &Resources,
3978	        resp: &Ivar<SchedResponse>,
3979	    ) -> Result<(), SkipTurn> {
3980	        if rs.poll_attempt > 0 {
3981	            // The thread is polling and hasn't been "remade" as runnable yet.
3982	            info!(
3983	                "[scheduler] >>>>>>>\n\n NONCOMMIT turn {}, SKIP dettid {} polling resource {:?}",
3984	                self.turn, dettid, rs
3985	            );
3986	            // Requeue the thread as a poller
3987	            let popped = self.run_queue.commit_tentative_pop();
3988	            assert_eq!(dettid, popped);
3989	            self.run_queue
3990	                .push_poller(dettid, self.get_priority(dettid), rs.poll_attempt);
3991	            trace!(
3992	                "[dtid {}] after deprioritizing polling request, run queue: {:?}",
3993	                dettid, &self.run_queue
3994	            );
3995	            self.upgrade_polled_to_runnable(dettid, rs); // Indicate the thread gets to run next time
3996	            self.skip_turn()
3997	        } else {
3998	            match rs.resources.len() {
3999	                0 => Ok(()),
4000	                1 => {
4001	                    let (rid, perm) = rs.resources.iter().next().unwrap();
4002	                    self.block_for_one_resource(
4003	                        dettid,
4004	                        rid,
4005	                        perm,
4006	                        rs.signal_interrupt_errno(),
4007	                        resp,
4008	                    )
4009	                }
4010	                _ => {
4011	                    panic!(
4012	                        "Requests for more than one resource at a time are not supported yet: {:?}",
4013	                        rs
4014	                    )
4015	                }
4016	            }
4017	        }
4018	    }
