4284	    /// Helper for priority changepoint logic
4285	    ///
4286	    /// Precondition: guest is stopped so that there is no chance the ivars are being used
4287	    /// concurrently while they are being cleared.
4288	    ///
4289	    /// Postcondition: Same as block_for_one_resource. However, always returns SkipTurn, because the
4290	    /// priority changepoint may not allow the current thread to continue in a regular turn (i.e.
4291	    /// doing actual work).
4292	    fn perform_priority_changepoint(
4293	        &mut self,
4294	        dettid: DetTid,
4295	
4296	        new_priority: Priority,
4297	        guest_time: LogicalTime,
