4808	    /// Atomically classify a same-raw-TID exec handoff and record its fresh
4809	    /// admission. The scheduler mutex serializes this method with `step2`, so a
4810	    /// drain can never observe only one half of the handoff.
4811	    fn replace_retired_run_queue_incarnation(&mut self, dtid: DetTid, intent: AdmitIntent) {
4812	        let disposition = self
4813	            .pending_run_queue_removals
4814	            .get_mut(&dtid)
4815	            .unwrap_or_else(|| {
4816	                panic!(
4817	                    "exec replacement {:?} has no retired run-queue incarnation",
4818	                    dtid
4819	                )
4820	            });
4821	        assert_eq!(
4822	            *disposition,
4823	            RemovalDisposition::Retire,
4824	            "exec replacement {:?} was classified more than once",
4825	            dtid
4826	        );
4827	        *disposition = RemovalDisposition::ReplaceThenAdmit;
4828	        assert!(
4829	            self.pending_run_queue_admissions
4830	                .insert(dtid, intent)
4831	                .is_none(),
4832	            "exec replacement {:?} already had a pending admission",
4833	            dtid
4834	        );
4835	    }
