5013	    /// Push `dtid` onto the run queue immediately, idempotently: a thread
5014	    /// already queued is left in place rather than enqueued twice.
5015	    fn admit_now(&mut self, dtid: DetTid, side: AdmitSide) {
5016	        if self.run_queue.contains_tid(dtid) {
5017	            return;
5018	        }
5019	        match side {
5020	            AdmitSide::Front => {
5021	                let _ = self.runqueue_push_front(dtid);
