5070	    /// Check if a thread is alive, but removed from run queue.
5071	    fn thread_status(&self, dtid: DetTid) -> ThreadStatus {
5072	        if self.run_queue.contains_tid(dtid) {
5073	            ThreadStatus::Running
5074	        } else {
5075	            // Check all the places a blocked thread could be hiding.
5076	            // TODO: this O(N) search could be made more efficient with more indexing structures.
5077	            for v in self.blocked.futex_waiters.values() {
5078	                for waiter in v {
5079	                    if waiter.dettid == dtid {
5080	                        return ThreadStatus::NotRunning;
5081	                    }
5082	                }
5083	            }
5084	            for (_, evt) in self.blocked.timed_waiters.iter() {
5085	                match evt {
5086	                    TimedEvent::ThreadEvt(dt) => {
5087	                        if dt == dtid {
5088	                            return ThreadStatus::NotRunning;
5089	                        }
5090	                    }
5091	                    TimedEvent::SignalEvt(_, _, _) => {}
5092	                }
5093	            }
5094	            if self.blocked.external_io_blockers.contains_key(&dtid) {
5095	                return ThreadStatus::NotRunning;
5096	            }
5097	            if self.blocked.rt_sigsuspend_blockers.contains_key(&dtid)
5098	                || self.blocked.child_waiters.contains_key(&dtid)
5099	                || self
5100	                    .blocked
5101	                    .physical_child_waiters
5102	                    .values()
5103	                    .any(|waiters| waiters.contains(&dtid))
5104	            {
5105	                return ThreadStatus::NotRunning;
5106	            }
5107	            if self.pending_run_queue_admissions.contains_key(&dtid) {
5108	                return ThreadStatus::Running;
5109	            }
5110	            ThreadStatus::Gone
5111	        }
5112	    }
