5149	    pub(crate) fn generate_partial_run_summary_for_log(
5150	        &mut self,
5151	        preemptions_to: Option<&PathBuf>,
5152	    ) -> anyhow::Result<(RunSummary, Option<String>)> {
5153	        let schedevent_replayed = self
5154	            .replayer
5155	            .as_ref()
5156	            .map(|r| r.events_popped)
5157	            .unwrap_or_default();
