5159	            .replayer
5160	            .as_ref()
5161	            .map(|r| {
5162	                r.desync_counts
5163	                    .values()
5164	                    .fold(Default::default(), |x: DesyncStats, y: &DesyncStats| x + *y)
5165	            })
5166	            .unwrap_or_default();
