5386	    // Returns the logical duration until any previously scheduled alarm, if any (zero otherwise).
5387	    pub fn register_alarm(
5388	        &mut self,
5389	        detpid: DetPid,
5390	        dettid: DetTid,
5391	        now: LogicalTime,
5392	        duration: LogicalTime,
5393	        interval: LogicalTime,
5394	        sig: Signal,
5395	    ) -> (LogicalTime, LogicalTime) {
5396	        let old = if duration == LogicalTime::ZERO {
5397	            // Alarm of 0 cancels any pending signal.
5398	            self.blocked.timed_waiters.remove_alarm(detpid)
5399	        } else {
5400	            let target_time = now + duration;
5401	            self.blocked
5402	                .timed_waiters
5403	                .insert_alarm(target_time, detpid, dettid, sig, interval)
5404	        };
5405	        if let Some((old_target_time, old_interval)) = old {
5406	            let remain_ns = old_target_time.as_nanos().saturating_sub(now.as_nanos());
5407	            (LogicalTime::from_nanos(remain_ns), old_interval)
5408	        } else {
5409	            // Return 0 if no previous alarm, as per https://man7.org/linux/man-pages/man2/alarm.2.html
5410	            (LogicalTime::ZERO, LogicalTime::ZERO)
5411	        }
5412	    }
