6225	    async fn observe_exec_reconnect_drain(timing: ExecReconnectTiming) -> ExecDrainObservation {
6226	        let config = Config {
6227	            sched_seed: Some(0x5107),
6228	            runs_post_fork: RunsPostFork::Random,
6229	            cancel_killed_thread_rpcs: true,
6230	            ..Config::default()
6231	        };
6232	        let sched = Arc::new(Mutex::new(Scheduler::new(&config)));
6233	        let global_time = Arc::new(Mutex::new(GlobalTime::new(&config)));
6234	        let leader = DetTid::from_raw(17);
6235	        let caller = DetTid::from_raw(18);
6236	        let lower = DetTid::from_raw(31);
6237	        let higher = DetTid::from_raw(37);
6238	        let barrier_parent = DetTid::from_raw(99);
6239	        let detpid = DetPid::from_raw(leader.as_raw());
6240	        let pre_exec_mm = MmId::initial(detpid);
6241	
6242	        let (caller_request, old_leader_request) = {
6243	            let mut s = sched.lock().unwrap();
6244	            s.thread_tree.add_child(leader, leader, true);
6245	            s.thread_tree.add_child(leader, caller, false);
6246	            register_known_thread(&mut s, leader);
6247	            register_known_thread(&mut s, caller);
6248	            // Give the destroyed leader a visibly different queue band. The
6249	            // replacement must use the caller's priority at the ordinary tail.
6250	            s.priorities.insert(leader, runqueue::FIRST_PRIORITY);
6251	            s.runqueue_push_back(leader);
6252	            s.runqueue_push_back(caller);
6253	            s.next_turns
6254	                .get(&leader)
6255	                .unwrap()
6256	                .req
6257	                .put(Ok(Resources::new(leader)));
6258	
6259	            register_known_thread(&mut s, lower);
6260	            register_known_thread(&mut s, higher);
6261	            s.admit_to_run_queue(lower, AdmitIntent::PostFork(RunsPostFork::Random));
6262	            s.admit_to_run_queue(higher, AdmitIntent::PostFork(RunsPostFork::Random));
6263	            // `step2` drains first, then this unresolved barrier returns
6264	            // `SkipTurn`, exposing the exact first-drain queue before step3 can
6265	            // tentatively select or rotate it.
6266	            s.vfork_barriers.insert(barrier_parent, None);
6267	            (
6268	                s.next_turns.get(&caller).unwrap().req.clone(),
6269	                s.next_turns.get(&leader).unwrap().req.clone(),
6270	            )
6271	        };
6272	
6273	        if matches!(timing, ExecReconnectTiming::BeforeDaemon) {
6274	            reconnect_nonleader_exec(
6275	                &mut sched.lock().unwrap(),
6276	                leader,
6277	                caller,
6278	                detpid,
6279	                pre_exec_mm,
6280	            );
6281	        } else if matches!(timing, ExecReconnectTiming::CallerResolvedBeforeReconnect) {
6282	            caller_request.put(Ok(Resources::new(caller)));
6283	        }
6284	
6285	        let turn_sched = sched.clone();
6286	        let turn_time = global_time.clone();
6287	        let turn = tokio::spawn(async move {
6288	            let last: Result<Resources, SkipTurn> = Err(SkipTurn);
6289	            do_a_turn_blocking(turn_sched, turn_time, &last).await
6290	        });
6291	
6292	        if let ExecReconnectTiming::AfterCallerWait { yields } = timing {
6293	            let mut saw_waiter = false;
6294	            for _ in 0..1_000 {
6295	                if caller_request.to_string() == "<ivar HasWaiter>" {
6296	                    saw_waiter = true;
6297	                    break;
6298	                }
6299	                tokio::task::yield_now().await;
6300	            }
6301	            assert!(saw_waiter, "daemon never waited on the exec caller request");
6302	            for _ in 0..yields {
6303	                tokio::task::yield_now().await;
6304	            }
6305	            reconnect_nonleader_exec(
6306	                &mut sched.lock().unwrap(),
6307	                leader,
6308	                caller,
6309	                detpid,
6310	                pre_exec_mm,
6311	            );
6312	        }
6313	
6314	        assert!(turn.await.expect("scheduler task panicked").is_err());
6315	        let mut s = sched.lock().unwrap();
6316	        let observation = ExecDrainObservation {
6317	            queue: s.run_queue.tids().copied().collect(),
6318	            next_post_fork_draw: s.child_runs_first_post_fork(RunsPostFork::Random),
6319	            turn: s.turn,
6320	            old_leader_registration_survived: s
6321	                .next_turns
6322	                .get(&leader)
6323	                .is_some_and(|turn| turn.req == old_leader_request),
6324	        };
6325	        if !matches!(timing, ExecReconnectTiming::CallerResolvedBeforeReconnect) {
6326	            assert_eq!(
6327	                observation
6328	                    .queue
6329	                    .iter()
6330	                    .filter(|tid| **tid == leader)
6331	                    .count(),
6332	                1
6333	            );
6334	            assert!(!observation.queue.contains(&caller));
6335	            assert!(!observation.old_leader_registration_survived);
6336	            assert!(s.pending_run_queue_admissions.is_empty());
6337	            assert!(s.pending_run_queue_removals.is_empty());
6338	        }
6339	        observation
6340	    }
