6362	    /// F6 (real-path regression): when the thread `step3_peek` tentatively
6363	    /// selected dies while the daemon awaits its request, `do_a_turn_blocking`
6364	    /// takes the `Err(ThreadExited)` fizzle arm. That arm MUST undo the tentative
6365	    /// pop so the selection does not outlive the turn; otherwise the next pass's
6366	    /// step2 removal drain calls `remove_tid` while `tentative_selection` is
6367	    /// still `Some`, tripping the run queue's transaction guard -- the "reconnect
6368	    /// panic moved one pass" defect (reachable in NORMAL async-DBT operation, not
6369	    /// just the reviewed edge case: any thread that exits during the await window
6370	    /// races here). This drives the ACTUAL async daemon function end to end
6371	    /// rather than poking `RunQueue` directly, which is the coverage gap the
6372	    /// pre-existing tests left. Positive control: after the fizzle the window is
6373	    /// closed and the following real step2 removal drain does not panic.
6374	    #[tokio::test]
6375	    async fn reconnect_fizzle_closes_window_so_next_removal_drain_is_safe() {
6376	        let config = Config::default();
6377	        let sched = Arc::new(Mutex::new(Scheduler::new(&config)));
6378	        let global_time = Arc::new(Mutex::new(GlobalTime::new(&config)));
6379	        let dead = DetTid::from_raw(7);
6380	        {
6381	            let mut s = sched.lock().unwrap();
6382	            s.priorities.insert(dead, DEFAULT_PRIORITY);
6383	            s.next_turns.insert(
6384	                dead,
6385	                ThreadNextTurn {
6386	                    dettid: dead,
6387	                    child_tid_addr: 0,
6388	                    // Request already resolved to `ThreadExited`: the daemon will
6389	                    // observe the thread died the moment it awaits `req.get()`.
6390	                    req: Ivar::full(Err(ThreadExited)),
6391	                    resp: Ivar::new(),
6392	                    protocol: Default::default(),
6393	                },
6394	            );
6395	            s.runqueue_push_back(dead);
6396	        }
6397	        let last: Result<Resources, SkipTurn> = Err(SkipTurn);
6398	
6399	        // Pass 1: step1 sees a filled request (quiescent), step3 tentatively
6400	        // pops `dead`, then `req.get().await` yields `Err(ThreadExited)`. The
6401	        // fizzle arm returns `SkipTurn` and undoes the tentative pop.
6402	        let first = do_a_turn_blocking(sched.clone(), global_time.clone(), &last).await;
6403	        assert!(first.is_err(), "fizzled reconnect turn skips");
6404	        assert!(
6405	            !sched.lock().unwrap().run_queue.tentative_pop_in_progress(),
6406	            "the ThreadExited arm must undo the tentative pop"
6407	        );
6408	
6409	        // Pass 2: the dead thread's run-queue removal is now buffered, exactly
6410	        // as a reconnect/kill handler would leave it. Because pass 1 closed the
6411	        // window, the real step2 removal drain calls `remove_tid` with
6412	        // `tentative_selection == None` and does NOT trip the guard. Pre-fix
6413	        // (window left open) this call panicked.
6414	        {
6415	            let mut s = sched.lock().unwrap();
6416	            s.deschedule_or_defer(dead);
6417	            s.next_turns.remove(&dead);
6418	            let _ = s.step2_process_blocked(&global_time);
6419	            assert!(!s.run_queue.contains_tid(dead), "dead thread drained out");
6420	            assert!(s.pending_run_queue_removals.is_empty());
6421	        }
6422	    }
