6424	    /// F8 (non-committing fizzle), part 1: the branch itself, both ways.
6425	    ///
6426	    /// NEGATIVE -- the defect. A selected thread whose `next_turns` entry
6427	    /// vanished during the daemon's post-await window must abandon the turn:
6428	    /// report `SkipTurn` (it commits nothing -- steps 4-7 are bypassed) AND
6429	    /// close the tentative window `step3_peek` opened. Before the fix this
6430	    /// branch fell through to `Ok(rsrcs)`, which `bump_global_time` reads as a
6431	    /// completed turn and answers with a virtual-time advance.
6432	    /// POSITIVE -- not inert. A thread that is still registered proceeds: `Ok`,
6433	    /// with its tentative selection left open for step4 to commit. Without this
6434	    /// side an `abort_turn_if_thread_vanished` that simply always skipped would
6435	    /// pass the negative and silently stall the scheduler.
6436	    #[test]
6437	    fn a_vanished_thread_aborts_its_turn_and_a_live_one_does_not() {
6438	        let config = Config::default();
6439	        let vanishing = DetTid::from_raw(11);
6440	        let live = DetTid::from_raw(13);
6441	
6442	        let mut sched = Scheduler::new(&config);
6443	        register_known_thread(&mut sched, vanishing);
6444	        register_known_thread(&mut sched, live);
6445	        sched.runqueue_push_back(vanishing);
6446	        sched.runqueue_push_back(live);
6447	
6448	        // NEGATIVE: retire `vanishing` after its selection was tentatively
6449	        // popped, exactly as teardown does inside the post-await window.
6450	        assert_eq!(
6451	            sched.run_queue.tentative_pop_tid(vanishing),
6452	            Some(vanishing)
6453	        );
6454	        assert!(sched.run_queue.tentative_pop_in_progress());
6455	        sched.next_turns.remove(&vanishing);
6456	        assert!(
6457	            sched.abort_turn_if_thread_vanished(vanishing).is_err(),
6458	            "a turn that bypasses steps 4-7 must report SkipTurn, never success: \
6459	             reporting Ok lets bump_global_time advance virtual time for a turn \
6460	             that committed nothing"
6461	        );
6462	        assert!(
6463	            !sched.run_queue.tentative_pop_in_progress(),
6464	            "the abandoned turn must also close its tentative window"
6465	        );
6466	
6467	        // POSITIVE: a still-registered thread is untouched and proceeds to
6468	        // step4 with its selection still open to commit.
6469	        assert_eq!(sched.run_queue.tentative_pop_tid(live), Some(live));
6470	        assert!(sched.run_queue.tentative_pop_in_progress());
6471	        assert!(
6472	            sched.abort_turn_if_thread_vanished(live).is_ok(),
6473	            "a live thread's turn must proceed"
6474	        );
6475	        assert!(
6476	            sched.run_queue.tentative_pop_in_progress(),
6477	            "a proceeding turn must keep its tentative selection open for step4"
6478	        );
6479	    }
