6481	    /// F8 (non-committing fizzle must not advance virtual time): both sides of
6482	    /// the consequence, stated directly against `bump_global_time` -- the code
6483	    /// that turns a turn's returned `Result` into a virtual-time decision.
6484	    ///
6485	    /// The defect: the fizzle arm where `req.get()` resolved `Ok` but the
6486	    /// thread's `next_turns` entry vanished before the daemon re-acquired the
6487	    /// lock skips steps 4-7, commits nothing, and used to fall through to
6488	    /// `Ok(rsrcs)` -- landing in the advancing branch below and adding a
6489	    /// DETLOG-visible tick for work that never happened. It now reports
6490	    /// `Err(SkipTurn)` like its `ThreadExited` sibling, so this pair of
6491	    /// assertions is what that fix buys.
6492	    ///
6493	    /// Deliberately NOT an end-to-end test of that arm. Reaching it requires
6494	    /// teardown to clear `next_turns` inside the host-scheduling gap between the
6495	    /// await resolving and the re-lock, and that gap is not constructible from a
6496	    /// test: the daemon quiescence check only proceeds once every thread's request
6497	    /// is already filled, so `req.get()` never suspends and there is no window a
6498	    /// test can hold open. An attempt to win the lock in that gap is a genuine
6499	    /// race that would usually lose (and deadlocks outright on a current-thread
6500	    /// runtime, where the daemon's blocking `sched.lock()` stalls the whole
6501	    /// executor). F6's `reconnect_fizzle_closes_window_so_next_removal_drain_is_
6502	    /// safe` does drive the real `do_a_turn_blocking` for the sibling arm.
6503	    ///
6504	    /// NEGATIVE: a skipped turn leaves virtual time exactly where it was. That is
6505	    /// what the F8 fix buys; before it, the non-committing arm reported `Ok` and
6506	    /// landed in the advancing branch.
6507	    /// POSITIVE: a committed, non-internal turn *does* advance it. Without this
6508	    /// side the negative would pass vacuously for a `bump_global_time` that had
6509	    /// simply stopped advancing time at all.
6510	    #[test]
6511	    fn virtual_time_advances_for_a_committed_turn_and_not_for_a_skipped_one() {
6512	        let config = Config::default();
6513	        let runnable = DetTid::from_raw(13);
6514	
6515	        // A non-empty run queue keeps the "only waiting on external events"
6516	        // guard from suppressing the advance for an unrelated reason.
6517	        let mut advancing = Scheduler::new(&config);
6518	        advancing.priorities.insert(runnable, DEFAULT_PRIORITY);
6519	        advancing.runqueue_push_back(runnable);
6520	        let advancing_time = Mutex::new(GlobalTime::new(&config));
6521	        let before_commit = advancing_time.lock().unwrap().as_nanos();
6522	        advancing.bump_global_time(&advancing_time, &Ok(Resources::new(runnable)));
6523	        let after_commit = advancing_time.lock().unwrap().as_nanos();
6524	        assert!(
6525	            after_commit > before_commit,
6526	            "a committed turn must advance virtual time ({before_commit:?} -> {after_commit:?})"
6527	        );
6528	
6529	        let mut skipping = Scheduler::new(&config);
6530	        skipping.priorities.insert(runnable, DEFAULT_PRIORITY);
6531	        skipping.runqueue_push_back(runnable);
6532	        let skipping_time = Mutex::new(GlobalTime::new(&config));
6533	        let before_skip = skipping_time.lock().unwrap().as_nanos();
6534	        skipping.bump_global_time(&skipping_time, &Err(SkipTurn));
6535	        let after_skip = skipping_time.lock().unwrap().as_nanos();
6536	        assert_eq!(
6537	            after_skip, before_skip,
6538	            "a skipped turn must not advance virtual time"
6539	        );
6540	    }
