6669	    fn vfork_registration_barrier_waits_for_deferred_child_at_continuation() {
6670	        // On a backend that defers the child spawn (e.g. KVM), the parent posts its continuation
6671	        // BEFORE the child registers. An unfulfilled barrier at continuation must be kept, not
6672	        // torn down as a failed clone; otherwise the late child panics on registration.
6673	        let config = Config {
6674	            backend_defers_vfork_child_registration: true,
6675	            ..Config::default()
6676	        };
6677	        let mut scheduler = Scheduler::new(&config);
6678	        let parent = DetTid::from_raw(3);
6679	        let child = DetTid::from_raw(5);
6680	        let op_id = ExternalOpId::new(parent, 7);
6681	        let mut continuation = Resources::new(parent);
6682	        continuation.insert(ResourceID::BlockedExternalContinue(op_id), Permission::RW);
6683	
6684	        scheduler.vfork_barriers.insert(parent, None);
6685	        scheduler.next_turns.insert(
6686	            parent,
6687	            ThreadNextTurn {
6688	                dettid: parent,
6689	                child_tid_addr: 0,
6690	                req: Ivar::full(Ok(continuation)),
6691	                resp: Ivar::new(),
6692	                protocol: Default::default(),
6693	            },
6694	        );
6695	
6696	        // Parent is at its continuation but the child has not registered: keep waiting, keep the
6697	        // barrier (the failed-clone teardown must NOT fire on a deferring backend).
6698	        assert!(scheduler.step2a_wait_for_vfork_barrier().is_err());
6699	        assert_eq!(scheduler.vfork_barriers.get(&parent), Some(&None));
6700	
6701	        // The deferred child registers; now the barrier is fulfilled and released.
6702	        scheduler.complete_vfork_registration(parent, child);
6703	        assert!(scheduler.step2a_wait_for_vfork_barrier().is_ok());
6704	        assert!(scheduler.vfork_barriers.is_empty());
