7529	            backend_reports_physical_process_exits: true,
7530	            ..Config::default()
7531	        };
7532	        let mut scheduler = Scheduler::new(&config);
7533	        let global_time = Arc::new(Mutex::new(GlobalTime::new(&config)));
7534	        let initial_time = global_time.lock().unwrap().as_nanos();
7535	        let exit_deadline = initial_time + LogicalTime::from_nanos(1_000);
7536	        let first_process = DetPid::from_raw(100);
7537	        let second_process = DetPid::from_raw(200);
7538	        let unrelated_process = DetPid::from_raw(300);
7539	
7540	        assert!(scheduler.begin_physical_process_exit(first_process));
7541	        assert!(!scheduler.begin_physical_process_exit(first_process));
7542	        assert!(scheduler.begin_physical_process_exit(second_process));
7543	        scheduler.register_alarm(
7544	            first_process,
7545	            first_process,
7546	            initial_time,
7547	            LogicalTime::from_nanos(1_000),
7548	            LogicalTime::ZERO,
7549	            Signal::SIGALRM,
7550	        );
7551	
7552	        assert!(scheduler.step2d_handle_empty_queue(&global_time).is_err());
7553	        assert_eq!(
7554	            scheduler
7555	                .blocked
7556	                .timed_waiters
7557	                .iter()
7558	                .map(|(time, _)| time)
7559	                .collect::<Vec<_>>(),
7560	            vec![exit_deadline]
7561	        );
7562	        assert_eq!(global_time.lock().unwrap().as_nanos(), initial_time);
7563	
7564	        assert!(!scheduler.complete_physical_process_exit(unrelated_process));
7565	        assert!(scheduler.complete_physical_process_exit(first_process));
7566	        assert!(!scheduler.complete_physical_process_exit(first_process));
7567	        assert!(scheduler.step2d_handle_empty_queue(&global_time).is_err());
7568	        assert!(!scheduler.blocked.timed_waiters.is_empty());
7569	        assert_eq!(global_time.lock().unwrap().as_nanos(), initial_time);
7570	
7571	        assert!(scheduler.complete_physical_process_exit(second_process));
7572	        assert!(scheduler.step2d_handle_empty_queue(&global_time).is_err());
7573	        assert!(scheduler.blocked.timed_waiters.is_empty());
7574	        assert_eq!(global_time.lock().unwrap().as_nanos(), exit_deadline);
