7577	    fn physical_wait_handoff_queue(completion_before_wait: bool) -> Vec<DetTid> {
7578	        let config = Config {
7579	            backend_reports_physical_process_exits: true,
7580	            ..Config::default()
7581	        };
7582	        let global_time = Arc::new(Mutex::new(GlobalTime::new(&config)));
7583	        let mut scheduler = Scheduler::new(&config);
7584	        let waiter = DetTid::from_raw(100);
7585	        let sibling = DetTid::from_raw(200);
7586	        let child = DetPid::from_raw(300);
7587	        register_known_thread(&mut scheduler, waiter);
7588	        register_known_thread(&mut scheduler, sibling);
7589	        scheduler.runqueue_push_back(waiter);
7590	        scheduler.runqueue_push_back(sibling);
7591	
7592	        assert!(scheduler.begin_physical_process_exit(child));
7593	        if completion_before_wait {
7594	            assert!(scheduler.complete_physical_process_exit(child));
7595	        }
7596	
7597	        assert_eq!(scheduler.run_queue.tentative_pop_tid(waiter), Some(waiter));
7598	        assert!(
7599	            scheduler
7600	                .block_for_one_resource(
7601	                    waiter,
7602	                    &ResourceID::WaitPhysicalChild(child),
7603	                    &Permission::W,
7604	                    None,
7605	                    &Ivar::new(),
7606	                )
7607	                .is_err()
7608	        );
7609	        assert_eq!(
7610	            scheduler.run_queue.tids().copied().collect::<Vec<_>>(),
7611	            vec![sibling]
7612	        );
7613	
7614	        if !completion_before_wait {
7615	            assert!(
7616	                scheduler.step2_process_blocked(&global_time).is_err(),
7617	                "a runnable sibling must not pass the pending physical-exit barrier"
7618	            );
7619	            assert_eq!(
7620	                scheduler.run_queue.tids().copied().collect::<Vec<_>>(),
7621	                vec![sibling]
7622	            );
7623	            assert!(scheduler.complete_physical_process_exit(child));
7624	        }
7625	
7626	        assert!(scheduler.step2_process_blocked(&global_time).is_ok());
7627	        assert!(scheduler.pending_run_queue_admissions.is_empty());
7628	        assert!(scheduler.blocked.physical_child_ready.contains(&waiter));
7629	        scheduler.run_queue.tids().copied().collect()
7630	    }
