7785	    /// Populate a scheduler with a deadlock's worth of blocked state, inserting
7786	    /// each collection in the caller's chosen order.
7787	    ///
7788	    /// `reverse` exists so the same logical state can be built two ways: the
7789	    /// report must not depend on insertion order, because `futex_waiters` is a
7790	    /// `HashMap`, `timed_out_futex_waiters` a `HashSet`, and
7791	    /// `Resources::resources` a `HashMap`.
7792	    fn deadlocked_scheduler(config: &Config, reverse: bool) -> Scheduler {
7793	        let mut scheduler = Scheduler::new(config);
7794	        let mm = MmId::initial(DetTid::from_raw(3));
7795	        let mut futexes = vec![
7796	            (FutexID::private(mm, 0x404100), 5),
7797	            (FutexID::private(mm, 0x404200), 7),
7798	            (FutexID::private(mm, 0x404300), 9),
7799	        ];
7800	        let mut tids = vec![3, 5, 7, 9];
7801	        if reverse {
7802	            futexes.reverse();
7803	            tids.reverse();
7804	        }
7805	
7806	        for (futex_id, dettid) in futexes {
7807	            scheduler
7808	                .blocked
7809	                .futex_waiters
7810	                .entry(futex_id)
7811	                .or_default()
7812	                .push(futex_waiter(dettid, u32::MAX));
7813	        }
7814	        for dettid in tids {
7815	            let dettid = DetTid::from_raw(dettid);
7816	            // A request carrying several resources: `Resources::resources` is a
7817	            // HashMap, so an unsorted render would vary here too.
7818	            let mut resources = Resources::new(dettid);
7819	            resources.insert(ResourceID::FutexWait, Permission::R);
7820	            resources.insert(ResourceID::MemAddrSpace(dettid), Permission::RW);
7821	            scheduler.next_turns.insert(
7822	                dettid,
7823	                ThreadNextTurn {
7824	                    dettid,
7825	                    child_tid_addr: 0,
7826	                    // A FULL ivar: `Debug` on this prints the parked waker's raw
7827	                    // host pointers, which is exactly what must not reach stderr.
7828	                    req: Ivar::full(Ok(resources)),
7829	                    resp: Ivar::new(),
7830	                    protocol: Default::default(),
7831	                },
7832	            );
7833	            scheduler.blocked.timed_out_futex_waiters.insert(dettid);
7834	        }
7835	        scheduler
7836	            .blocked
7837	            .timed_waiters
7838	            .insert(LogicalTime::INDEFINITE, DetTid::from_raw(11));
7839	        scheduler
7840	    }
