7902	    /// A `pause(2)` registers `LogicalTime::INDEFINITE`, which is a sentinel for
7903	    /// "no deadline", not a deadline. With nothing else left to run, the guest is
7904	    /// permanently blocked and must be reported as such -- never woken.
7905	    #[test]
7906	    fn indefinite_waiter_alone_is_reported_as_a_deadlock() {
7907	        let config = Config::default();
7908	        let mut scheduler = Scheduler::new(&config);
7909	        let global_time = Arc::new(Mutex::new(GlobalTime::new(&config)));
7910	        let initial_time = global_time.lock().unwrap().as_nanos();
7911	
7912	        scheduler
7913	            .blocked
7914	            .timed_waiters
7915	            .insert(LogicalTime::INDEFINITE, DetTid::from_raw(100));
7916	
7917	        assert!(scheduler.step2d_handle_empty_queue(&global_time).is_err());
7918	
7919	        // Asserting the verdict by value, not by catching a panic: the report is
7920	        // recorded for `sched_loop_inner` to print and exit on, so the text is
7921	        // checkable here rather than only through `#[should_panic]`.
7922	        let report = scheduler
7923	            .take_terminal_deadlock()
7924	            .expect("an indefinite waiter with nothing runnable is a terminal deadlock");
7925	        assert!(
7926	            report.contains("thread(s) waiting indefinitely"),
7927	            "unexpected report:\n{report}"
7928	        );
7929	        // Taking it is destructive, and the indefinite waiter is never woken.
7930	        assert!(scheduler.take_terminal_deadlock().is_none());
7931	        assert_eq!(global_time.lock().unwrap().as_nanos(), initial_time);
7932	        assert!(!scheduler.blocked.timed_waiters.is_empty());
7933	    }
