117	pub(super) struct ProcessSignalRegistry {
118	    processes: Mutex<BTreeMap<(i32, u64), Weak<ProcessBinding>>>,
119	    // Logical process ancestry is independent of host join-handle placement.
120	    // It is retained by exact generation until a wait consumes a zombie or an
121	    // exit-time auto-reap decision removes it. This is the fail-closed boundary
122	    // for reparenting, which this change does not claim to implement.
123	    family: Mutex<ProcessFamilyState>,
124	    // Run-scoped at-most-once admission. Standard-signal coalescing is not an
125	    // operation ledger: after dequeue, the same child could otherwise enqueue
126	    // a second SIGCHLD. Retain exact generations until the run ends.
127	    child_publications: Mutex<BTreeMap<(i32, u64), ChildPublicationRecord>>,
128	    // No callbacks or G references. An eventual owner must make its own run
129	    // terminal after saving FailedAfterCommit. This latch refuses further
130	    // publication; it is not a substitute for that owner transition.
131	    failure: Mutex<Option<PublicationFailure>>,
132	    controlled: AtomicBool,
133	    permits: Mutex<BTreeMap<(i32, u64, i32, u64), RegisteredPermit>>,
134	    completed_permits: Mutex<BTreeMap<(i32, u64, i32, u64), reverie::SignalDeliveryPermit>>,
