140	impl ProcessSignalRegistry {
141	    pub(super) fn register(
142	        &self,
143	        state: &LoadedStaticElf,
144	        files: &Arc<Mutex<FileTableState>>,
145	        generation: u64,
146	        parent: Option<SignalProcessId>,
147	    ) -> Result<Arc<ProcessBinding>, SignalProcessId> {
148	        let identity = SignalProcessId {
149	            tgid: reverie::Pid::from_raw(state.pid),
150	            generation,
151	        };
152	        // Successful exec and same-process executor reconstruction retain the
153	        // process generation; they are not a fork edge and cannot make a
154	        // process its own child.
155	        let parent = parent.filter(|candidate| *candidate != identity);
156	        let binding = Arc::new(ProcessBinding {
157	            identity,
158	            parent,
159	            transaction: Arc::downgrade(&state.signal_transaction),
160	            lifecycle: Arc::downgrade(&state.task_lifecycle),
161	            image: Mutex::new(CurrentImage {
162	                revision: ImageRevision(Arc::new(())),
163	                files: Arc::downgrade(files),
164	                signals: Arc::downgrade(&state.process_signals),
165	            }),
166	        });
167	        if let Some(parent) = parent {
168	            let mut family = self.family.lock().unwrap_or_else(|p| p.into_inner());
169	            let parent_key = process_key(parent);
170	            if family.terminal.contains_key(&parent_key) {
171	                return Err(parent);
172	            }
173	            let previous = family
174	                .direct_children
175	                .entry(parent_key)
176	                .or_default()
177	                .insert(process_key(binding.identity), DirectChildState::Live);
178	            debug_assert!(previous.is_none(), "duplicate KVM child process generation");
179	        }
180	        let mut processes = self.processes.lock().unwrap_or_else(|p| p.into_inner());
181	        processes.retain(|_, process| process.strong_count() != 0);
182	        processes.insert((state.pid, generation), Arc::downgrade(&binding));
183	        Ok(binding)
184	    }
185	
186	    fn lookup(&self, identity: SignalProcessId) -> Option<Arc<ProcessBinding>> {
187	        self.processes
188	            .lock()
189	            .unwrap_or_else(|p| p.into_inner())
190	            .get(&(identity.tgid.as_raw(), identity.generation))?
191	            .upgrade()
192	    }
193	
194	    /// Freeze the exact process generation at its first exact task failure.
195	    /// Descendants may still finish successfully while the runtime unwinds,
196	    /// but their completion is teardown rather than a new logical child-exit
197	    /// publication to the failed parent.
198	    pub(super) fn record_process_failure(&self, process: SignalProcessId) {
199	        self.family
200	            .lock()
201	            .unwrap_or_else(|p| p.into_inner())
202	            .terminal
203	            .entry(process_key(process))
204	            .or_insert(ProcessFamilyExit::Failed);
205	    }
206	
207	    /// Freeze one process's terminal parent/wait policy at the authoritative
208	    /// lifecycle transition. Host join completion and the later Tool callback
209	    /// only consume this snapshot; they cannot resample a parent's newer
210	    /// SIGCHLD disposition.
211	    pub(super) fn record_process_exit(
212	        &self,
213	        process: SignalProcessId,
214	        status: reverie::ExitStatus,
215	    ) -> ProcessFamilyExit {
216	        if let Some(exit) = self
217	            .family
218	            .lock()
219	            .unwrap_or_else(|p| p.into_inner())
220	            .terminal
221	            .get(&process_key(process))
222	            .copied()
223	        {
224	            return exit;
225	        }
226	
227	        let binding = self.lookup(process);
228	        let parent_identity = binding.as_ref().and_then(|binding| binding.parent);
229	        let is_root = parent_identity.is_none();
230	        let parent_binding = parent_identity.and_then(|parent| self.lookup(parent));
231	        let parent_transaction = parent_binding
232	            .as_ref()
233	            .and_then(|binding| binding.transaction.upgrade());
234	        let _parent_transaction = parent_transaction
235	            .as_ref()
236	            .map(|transaction| transaction.lock().unwrap_or_else(|p| p.into_inner()));
237	        let parent_snapshot = parent_binding.as_ref().and_then(|parent_binding| {
238	            let parent = parent_identity?;
239	            let lifecycle = parent_binding.lifecycle.upgrade()?;
240	            let lifecycle = lifecycle.lock().unwrap_or_else(|p| p.into_inner());
241	            if !lifecycle.contains_process(parent.tgid.as_raw(), parent.generation) {
242	                return None;
243	            }
244	            let image = parent_binding
245	                .image
246	                .lock()
247	                .unwrap_or_else(|p| p.into_inner())
248	                .clone();
249	            let signals = image.signals.upgrade()?;
250	            let signals = signals.lock().unwrap_or_else(|p| p.into_inner());
251	            let action = signals
252	                .dispositions
253	                .get(&libc::SIGCHLD)
254	                .copied()
255	                .unwrap_or_default();
256	            let disposition = if action.is_ignored() {
257	                PublicationDisposition::Ignored
258	            } else if action.handler == libc::SIG_DFL as u64 {
259	                PublicationDisposition::Default
260	            } else {
261	                PublicationDisposition::Caught
262	            };
263	            let waitable = !action.is_ignored() && action.flags & libc::SA_NOCLDWAIT as u64 == 0;
264	            let pending_generation = signals.pending_generation(libc::SIGCHLD);
265	            Some((parent, disposition, waitable, pending_generation))
266	        });
267	
268	        let mut family = self.family.lock().unwrap_or_else(|p| p.into_inner());
269	        if let Some(exit) = family.terminal.get(&process_key(process)).copied() {
270	            return exit;
271	        }
272	        let blocking_descendant = family
273	            .direct_children
274	            .get(&process_key(process))
275	            .and_then(|children| children.keys().next().copied())
276	            .map(|(tgid, generation)| SignalProcessId {
277	                tgid: reverie::Pid::from_raw(tgid),
278	                generation,
279	            });
280	        let parent_is_terminal = parent_identity.is_some_and(|parent| {
281	            let parent = process_key(parent);
282	            family.terminal.contains_key(&parent)
283	        });
284	        let exit = if is_root {
285	            ProcessFamilyExit::Root
286	        } else if parent_is_terminal {
287	            if let Some(parent) = parent_identity {
288	                let parent_key = process_key(parent);
289	                if let Some(children) = family.direct_children.get_mut(&parent_key) {
290	                    children.remove(&process_key(process));
291	                    if children.is_empty() {
292	                        family.direct_children.remove(&parent_key);
293	                    }
294	                }
295	            }
296	            ProcessFamilyExit::RunTeardownChild { status }
297	        } else if let Some(child) = blocking_descendant {
298	            ProcessFamilyExit::DescendantReparentingUnsupported { child }
299	        } else if let Some((parent, disposition, waitable, pending_generation)) = parent_snapshot {
300	            let completion = reverie::ChildExitCompletion {
301	                parent,
302	                child: process,
303	                status,
304	                waitable,
305	                uid: 0,
306	                user_ticks: 0,
307	                system_ticks: 0,
308	            };
309	            let parent_key = process_key(parent);
310	            let child_key = process_key(process);
311	            if waitable {
312	                let relation = family
313	                    .direct_children
314	                    .get_mut(&parent_key)
315	                    .and_then(|children| children.get_mut(&child_key));
316	                if let Some(relation) = relation {
317	                    *relation = DirectChildState::WaitableZombie;
318	                } else {
319	                    return ProcessFamilyExit::DescendantReparentingUnsupported { child: process };
320	                }
321	            } else if let Some(children) = family.direct_children.get_mut(&parent_key) {
322	                children.remove(&child_key);
323	                if children.is_empty() {
324	                    family.direct_children.remove(&parent_key);
325	                }
326	            }
327	            ProcessFamilyExit::Child(ChildExitSnapshot {
328	                completion,
329	                disposition,
330	                pending_generation,
331	            })
332	        } else {
333	            ProcessFamilyExit::DescendantReparentingUnsupported { child: process }
334	        };
335	        family.terminal.insert(process_key(process), exit);
336	        exit
337	    }
338	
339	    pub(super) fn process_family_exit(
340	        &self,
341	        process: SignalProcessId,
342	    ) -> Option<ProcessFamilyExit> {
343	        self.family
344	            .lock()
345	            .unwrap_or_else(|p| p.into_inner())
346	            .terminal
347	            .get(&process_key(process))
348	            .copied()
349	    }
