351	    pub(super) fn consume_child_wait(&self, parent: SignalProcessId, child_pid: i32) -> bool {
352	        let mut family = self.family.lock().unwrap_or_else(|p| p.into_inner());
353	        let parent_key = process_key(parent);
354	        let Some(children) = family.direct_children.get_mut(&parent_key) else {
355	            return false;
356	        };
357	        let child = children.iter().find_map(|(key, state)| {
358	            (key.0 == child_pid && *state == DirectChildState::WaitableZombie).then_some(*key)
359	        });
360	        let Some(child) = child else {
361	            return false;
362	        };
363	        children.remove(&child);
364	        if children.is_empty() {
365	            family.direct_children.remove(&parent_key);
366	        }
367	        true
368	    }
369	
370	    pub(super) fn control(self: &Arc<Self>) -> ProcessSignalControl {
371	        ProcessSignalControl(Arc::downgrade(self))
372	    }
373	}
