786	fn child_exit_signal_event(
787	    completion: reverie::ChildExitCompletion,
788	) -> Result<SignalEvent, PublicationRejection> {
789	    if completion.user_ticks < 0 || completion.system_ticks < 0 {
790	        return Err(PublicationRejection::InvalidCompletion);
791	    }
792	    let (code, status) = match completion.status {
793	        reverie::ExitStatus::Exited(status) if (0..=i32::from(u8::MAX)).contains(&status) => {
794	            (libc::CLD_EXITED, status)
795	        }
796	        reverie::ExitStatus::Exited(_) => {
797	            return Err(PublicationRejection::InvalidCompletion);
798	        }
799	        reverie::ExitStatus::Signaled(signal, true) => (libc::CLD_DUMPED, signal as libc::c_int),
800	        reverie::ExitStatus::Signaled(signal, false) => (libc::CLD_KILLED, signal as libc::c_int),
801	    };
802	    let mut info = [0; reverie::SIGNAL_INFO_SIZE];
803	    info[..4].copy_from_slice(&libc::SIGCHLD.to_ne_bytes());
804	    info[8..12].copy_from_slice(&code.to_ne_bytes());
805	    info[16..20].copy_from_slice(&completion.child.tgid.as_raw().to_ne_bytes());
806	    info[20..24].copy_from_slice(&completion.uid.to_ne_bytes());
807	    info[24..28].copy_from_slice(&status.to_ne_bytes());
808	    info[32..40].copy_from_slice(&completion.user_ticks.to_ne_bytes());
809	    info[40..48].copy_from_slice(&completion.system_ticks.to_ne_bytes());
810	    let event = SignalEvent::new(
811	        libc::SIGCHLD,
812	        info,
813	        reverie::SignalTarget::Process {
814	            pid: completion.parent.tgid,
815	        },
816	    );
817	    event.map_err(|_| PublicationRejection::InvalidCompletion)
818	}
