938	    // returned Error too, so root completion retains the committed publication
939	    // receipt as secondary cleanup rather than losing it.
940	    registry
941	        .reported_failure
942	        .lock()
943	        .unwrap_or_else(|p| p.into_inner())
944	        .get_or_insert(published);
