    state.thread_signals.lock().observe_ignored = observe_ignored;
    let task_generation = state
        .task_lifecycle
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner())
        .register_with_signals(
            state.tid,
            state.pid,
            state.pgid,
            state.dumpable,
