167	        &self,
168	        tid: Pid,
169	        _: Option<(Pid, &Self::ThreadState)>,
170	    ) -> Self::ThreadState {
171	        (tid.as_raw(), false)
172	    }
173	    async fn handle_thread_start<G: Guest<Self>>(
174	        &self,
175	        guest: &mut G,
176	    ) -> Result<(), reverie::Error> {
177	        assert_eq!(guest.thread_state(), &(self.pid, false));
178	        guest.thread_state_mut().1 = true;
179	        self.control.record("start", self.pid, unsafe {
180	            libc::syscall(libc::SYS_gettid)
181	        });
182	        HOST_EXIT.with(|exit| {
183	            assert!(
184	                exit.0
185	                    .borrow_mut()
186	                    .replace((self.control.clone(), self.pid))
187	                    .is_none()
188	            );
189	        });
190	        Ok(())
191	    }
192	    async fn handle_syscall_event<G: Guest<Self>>(
193	        &self,
194	        guest: &mut G,
195	        syscall: Syscall,
196	    ) -> Result<i64, reverie::Error> {
197	        assert_eq!(guest.thread_state(), &(self.pid, true));
198	        if syscall.number() == Sysno::getpid {
199	            assert_eq!(self.pid, 1);
200	            let count = if (2..=5).contains(&self.mode) { 2 } else { 1 };
201	            let mut children = Vec::new();
202	            for expected in 2..2 + count {
203	                let child = guest.inject(Fork::new()).await?;
204	                assert_eq!(child, expected);
205	                children.push(child as i32);
206	            }
207	            if matches!(self.mode, 2 | 6) {
208	                self.control
209	                    .wait_for(|state| {
210	                        children.iter().all(|pid| {
211	                            state
212	                                .events
213	                                .iter()
214	                                .any(|event| event.kind == "wait-event" && event.pid == *pid)
215	                        })
216	                    })
217	                    .await;
218	                for child in &children {
219	                    // Waitable completion is published after the callback's
220	                    // synchronous prefix and before its held remainder. This
221	                    // actual wait moves its live handle into completed_processes.
222	                    let wait = Syscall::from_raw(
223	                        Sysno::wait4,
224	                        SyscallArgs::new(*child as usize, 0, libc::WNOHANG as usize, 0, 0, 0),
225	                    );
226	                    assert_eq!(guest.inject(wait).await?, i64::from(*child));
227	                    self.control.record("wait-collected", *child, 0);
228	                }
229	            } else {
230	                let blocked = *children.last().unwrap();
231	                self.control
232	                    .wait_for(|state| {
233	                        state
234	                            .events
235	                            .iter()
236	                            .any(|event| event.kind == "blocked" && event.pid == blocked)
237	                            && (self.mode < 3
238	                                || state
239	                                    .events
240	                                    .iter()
241	                                    .any(|event| event.kind == "process-exit" && event.pid == 2))
242	                    })
243	                    .await;
244	            }
245	            {
246	                let mut state = self.control.state.lock().unwrap();
247	                state.parent_ready = true;
248	                state.events.push(Event {
249	                    kind: "parent-ready",
250	                    pid: self.pid,
251	                    value: i64::from(self.mode),
252	                });
253	                self.control.changed.notify_all();
254	            }
255	            if matches!(self.mode, 1 | 5) {
256	                return Ok(i64::from(children[0]));
257	            }
258	            // The same callback has registered its children and now terminates.
